def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]

    # Find maximal diagonal runs of matching non-background cells.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue

                run_set = set(run)

                def clutter(point):
                    y, x = point
                    return sum(
                        1 for dy in (-1, 0, 1) for dx in (-1, 0, 1)
                        if (dy or dx)
                        and 0 <= y + dy < h and 0 <= x + dx < w
                        and grid[y + dy][x + dx] != bg
                        and (y + dy, x + dx) not in run_set
                    )

                # Continue outward from the less-cluttered end of the run.
                start, end = run[0], run[-1]
                if clutter(start) <= clutter(end):
                    y, x = start
                    sy, sx = -dr, -dc
                else:
                    y, x = end
                    sy, sx = dr, dc

                y += sy
                x += sx
                while 0 <= y < h and 0 <= x < w and grid[y][x] == bg:
                    out[y][x] = color
                    y += sy
                    x += sx

    return out
